39	  };
40	  auth: {
41	    ws: WsAuthenticator;
42	    http?: HttpAuthMiddleware;
43	  };
44	  orchestrator?: {
45	    maxToolRounds?: number;
46	    /** How long one tool call may take before it is abandoned and answered with a timeout result; default 30000, and 0 waits forever. */
47	    toolTimeoutMs?: number;
48	    contextConfig?: Partial<ContextConfig>;
49	    /** Lifecycle hooks: called before and after each phase of processing a user message. */
50	    hooks?: OrchestratorHooks;
51	  };
52	  // Replaces the package's logger process-wide, not per engine: there is one `log` per process.
53	  logger?: Logger;
54	  onConnect?: (session: ChatSession, connection: ConnectInfo) => void | Promise<void>;
55	  onDisconnect?: (sessionId: string) => void | Promise<void>;
56	}
57	
58	export interface HalEngine extends HalServer {
59	  app: ReturnType<typeof createApp>;
60	  orchestrator: ReturnType<typeof createChatOrchestrator>;
61	  toolRegistry: ToolRegistry;
62	}
63	
64	export function createHalEngine(config: HalEngineConfig): HalEngine {
65	  // Before anything else builds, so a supplied logger receives this engine's first line.
66	  if (config.logger) setLogger(config.logger);
67	
68	  const toolRegistry = config.tools ?? new ToolRegistry();
69	  const sessionStore = config.session ?? new InMemorySessionStore();
70	  const basePath = config.transport?.basePath ?? '/hal';
71	
72	  const baseProvider = createProvider(config.provider);
73	  const provider = config.resilience ? withRetry(baseProvider, config.resilience) : baseProvider;
74	  const promptBuilder = new PromptBuilder(config.prompt);
75	  const orchestrator = createChatOrchestrator(provider, promptBuilder, toolRegistry, {
76	    maxToolRounds: config.orchestrator?.maxToolRounds,
77	    toolTimeoutMs: config.orchestrator?.toolTimeoutMs,
78	    contextConfig: config.orchestrator?.contextConfig,
79	    hooks: config.orchestrator?.hooks,
80	    sessionStore,
81	  });
82	
83	  const app = createApp({
84	    corsOrigin: config.transport?.corsOrigin,
85	    basePath,
86	    authMiddleware: config.auth.http,
87	    orchestrator,
88	    sessionStore,
89	    additionalRoutes: config.transport?.additionalRoutes,
90	    rootRoutes: config.transport?.rootRoutes,
91	    errorHandler: config.transport?.errorHandler,
92	  });
93	
94	  const halServer = createServer({
95	    app,
96	    wsAuth: config.auth.ws,
97	    sessionStore,
98	    orchestrator,
