1	import {once} from 'node:events';
2	import type {AddressInfo} from 'node:net';
3	import {WebSocket} from 'ws';
4	import type {Express} from 'express';
5	import {createServer} from './createServer.js';
6	import {HAL_WS_SUBPROTOCOL} from './ws/subprotocol.js';
7	import type {SessionResumeOptions} from './ws/sessionResume.js';
8	import {answeringOrchestrator} from './wsTestSupport.js';
9	import {InMemorySessionStore} from '../infrastructure/stores/inMemorySessionStore.js';
10	import type {ChatOrchestrator} from '../orchestration/chatOrchestrator.js';
11	import type {MessageChunk} from '../types/ai.js';
12	import type {ConnectedMessage} from '../types/messages.js';
13	import type {SessionEntry} from '../types/session.js';
14	import type {SessionStore} from '../types/sessionStore.js';
15	import {setLogger} from '../shared/logger.js';
16	
17	// Real upgrades over a real socket: what a reconnect is sent is the contract, and no double can observe it.
18	
19	interface Frame {
20	  type: string;
21	  sessionId?: string;
22	  resumed?: boolean;
23	  entryCount?: number;
24	  resumeFailure?: string;
25	  index?: number;
26	  entry?: SessionEntry;
27	}
28	
29	const NEVER_ISSUED = '0f1e2d3c-4b5a-4968-8776-655443322110';
30	const RESUME_ON: SessionResumeOptions = {enabled: true};
31	const LATEST_ON: SessionResumeOptions = {enabled: true, latest: true};
32	const HALF_ANSWER: SessionEntry = {
33	  role: 'assistant',
34	  content: 'half',
35	  timestamp: '2026-09-30T08:00:01.000Z',
36	  isStreaming: true,
37	};
38	
39	// A tool's suppression lands while the answer is still open, as when a provider ends a tool round with no stop.
40	const suppressingMidAnswer: ChatOrchestrator = {
41	  processMessage: async () => 'before after',
42	  async *processMessageStream(): AsyncGenerator<MessageChunk> {
43	    yield {type: 'text', text: 'before'};
44	    yield {type: 'suppress_output'} as unknown as MessageChunk;
45	    yield {type: 'text', text: ' after'};
46	    yield {type: 'stop', stopReason: 'end_turn'};
47	  },
48	};
49	
50	const servers: Array<ReturnType<typeof createServer>> = [];
51	const clients: WebSocket[] = [];
52	
53	const eventually = async (check: () => boolean): Promise<void> => {
54	  for (let attempt = 0; attempt < 50 && !check(); attempt++) await new Promise(resolve => setTimeout(resolve, 10));
55	};
56	
57	// Silenced for the whole file: the server logs every connection and close, and these tests read frames, not logs.
58	beforeAll(() => {
59	  setLogger({debug: () => undefined, info: () => undefined, warn: () => undefined, error: () => undefined});
60	});
61	
62	afterAll(() => {
63	  setLogger();
64	});
65	
66	// Each server sees its sockets close before it stops, so no close is logged after the logger above is restored.
67	afterEach(async () => {
68	  for (const client of clients.splice(0)) client.terminate();
69	  for (const hal of servers.splice(0)) {
70	    const {wss} = hal;
71	    await eventually(() => wss.clients.size === 0);
72	    await hal.stop();
73	  }
74	});
75	
76	// The authenticated user is read per upgrade, so one test can reconnect as someone else.
77	const startEngine = async (
78	  store: SessionStore,
79	  resume?: SessionResumeOptions,
80	  orchestrator: ChatOrchestrator = answeringOrchestrator
81	) => {
82	  const auth = {userId: 'u1'};
83	  const connects: Array<{sessionId: string; resumed: boolean}> = [];
84	  const disconnected: string[] = [];
85	  const hal = createServer({
86	    app: (() => undefined) as unknown as Express,
87	    wsAuth: async () => ({id: auth.userId}),
88	    sessionStore: store,
89	    orchestrator,
90	    resume,
91	    onConnect: (session, {resumed}) => void connects.push({sessionId: session.sessionId, resumed}),
92	    onDisconnect: sessionId => void disconnected.push(sessionId),
93	  });
94	  // Resolves once the server itself has seen its first socket close, which the client's own close can precede.
95	  const firstServerClose = new Promise<void>(resolve => {
96	    hal.wss.once('connection', socket => socket.once('close', () => resolve()));
97	  });
98	  await hal.start(0);
99	  servers.push(hal);
100	  const {port} = hal.server.address() as AddressInfo;
101	  return {auth, connects, disconnected, firstServerClose, base: `ws://127.0.0.1:${port}/hal/ws`};
102	};
103	
104	const open = (url: string, token = 't'): WebSocket => {
105	  const client = new WebSocket(url, [HAL_WS_SUBPROTOCOL, token]);
106	  clients.push(client);
107	  return client;
108	};
109	
110	// One question answered and the socket closed, returning the id the connected frame announced.
111	const firstTurn = async (base: string): Promise<string> => {
112	  const client = open(base);
113	  let sessionId = '';
114	  await new Promise<void>(resolve => {
115	    client.on('message', raw => {
116	      const frame = JSON.parse(String(raw)) as Frame;
117	      if (frame.type === 'connected') sessionId = frame.sessionId ?? '';
118	      if (frame.type === 'connected') client.send(JSON.stringify({type: 'user_message', content: 'hello'}));
119	      if (frame.type === 'stream_end') resolve();
120	    });
121	  });
122	  client.close();
123	  await once(client, 'close');
124	  return sessionId;
125	};
126	
127	// A ping sent on connect is a barrier: its pong can only follow every frame the replay wrote.
128	const connectAndSettle = async (url: string, token?: string): Promise<Frame[]> => {
129	  const client = open(url, token);
130	  const frames: Frame[] = [];
131	  await new Promise<void>(resolve => {
132	    client.on('message', raw => {
133	      const frame = JSON.parse(String(raw)) as Frame;
134	      frames.push(frame);
135	      if (frame.type === 'connected') client.send(JSON.stringify({type: 'ping', timestamp: 1}));
136	      if (frame.type === 'pong') resolve();
137	    });
138	  });
139	  return frames;
140	};
141	
142	const upserts = (frames: Frame[]) =>
143	  frames.filter(frame => frame.type === 'entry_upsert').map(({index, entry}) => ({index, entry}));
144	
145	const shapeOf = (frames: Frame[]) => ({
146	  keys: Object.keys(frames[0]).sort(),
147	  resumed: frames[0].resumed,
148	  resumeFailure: frames[0].resumeFailure,
149	  types: frames.map(frame => frame.type),
150	});
151	
152	const deferredRelease = () => {
153	  let release = (): void => undefined;
154	  const until = new Promise<void>(resolve => {
155	    release = resolve;
156	  });
157	  return {until, release: () => release()};
158	};
159	
160	// Each stored conversation holds one user entry, sent at the given time and reading as its own id.
161	const storeWith = (conversations: Array<[sessionId: string, userId: string, sentAt: string]>): InMemorySessionStore => {
162	  const store = new InMemorySessionStore();
163	  for (const [sessionId, userId, sentAt] of conversations) {
164	    const {entries} = store.create(sessionId, userId);
165	    entries.push({role: 'user', content: sessionId, timestamp: sentAt});
166	  }
167	  return store;
168	};
169	
170	// A store with only the required members, so an optional one can be added, replaced or left out per test.
171	const delegatingTo = (inner: InMemorySessionStore): SessionStore => ({
172	  create: (sessionId, userId, options) => inner.create(sessionId, userId, options),
173	  get: sessionId => inner.get(sessionId),
174	  delete: sessionId => inner.delete(sessionId),
175	  count: () => inner.count(),
176	  clear: () => inner.clear(),
177	});
178	
179	describe('resuming a conversation on reconnect', () => {
180	  it('with resume absent, answers a reconnect naming the first id with a new id and no replay', async () => {
181	    const {base} = await startEngine(new InMemorySessionStore());
182	    const first = await firstTurn(base);
183	
184	    const frames = await connectAndSettle(`${base}?sessionId=${first}`);
185	
186	    expect({newId: frames[0].sessionId !== first, shape: shapeOf(frames)}).toEqual({
187	      newId: true,
188	      shape: {
189	        keys: ['examplePrompts', 'message', 'sessionId', 'type'],
190	        resumed: undefined,
191	        types: ['connected', 'pong'],
192	      },
193	    });
194	  });
195	
196	  it('with resume on, answers the owner reconnecting with resumed true, entryCount 2 and both stored entries', async () => {
197	    const store = new InMemorySessionStore();
198	    const {base} = await startEngine(store, RESUME_ON);
199	    const first = await firstTurn(base);
200	
201	    const frames = await connectAndSettle(`${base}?sessionId=${first}`);
202	
203	    const stored = JSON.parse(JSON.stringify((await store.get(first))?.entries)) as SessionEntry[];
204	    expect({connected: frames[0], replay: upserts(frames)}).toMatchObject({
205	      connected: {type: 'connected', sessionId: first, resumed: true, entryCount: 2},
206	      replay: [
207	        {index: 0, entry: stored[0]},
208	        {index: 1, entry: stored[1]},
209	      ],
210	    });
211	  });
212	
213	  it('answers another user naming the id exactly as it answers an id that was never issued', async () => {
214	    const {auth, base} = await startEngine(new InMemorySessionStore(), RESUME_ON);
215	    const first = await firstTurn(base);
216	    auth.userId = 'u2';
217	
218	    const otherUser = await connectAndSettle(`${base}?sessionId=${first}`);
219	    const neverIssued = await connectAndSettle(`${base}?sessionId=${NEVER_ISSUED}`);
220	
221	    expect({fresh: otherUser[0].sessionId !== first, otherUser: shapeOf(otherUser)}).toEqual({
222	      fresh: true,
223	      otherUser: shapeOf(neverIssued),
224	    });
225	  });
226	
227	  it('answers a never-issued id with resumed false, resumeFailure unknown, and no replay or error', async () => {
228	    const {base} = await startEngine(new InMemorySessionStore(), RESUME_ON);
229	
230	    const frames = await connectAndSettle(`${base}?sessionId=${NEVER_ISSUED}`);
231	
232	    expect(shapeOf(frames)).toEqual({
233	      keys: ['examplePrompts', 'message', 'resumeFailure', 'resumed', 'sessionId', 'type'],
234	      resumed: false,
235	      resumeFailure: 'unknown',
236	      types: ['connected', 'pong'],
237	    });
238	  });
239	
240	  it('never adopts a requested id as a key: one session, under the id the server minted', async () => {
241	    const store = new InMemorySessionStore();
242	    const {base} = await startEngine(store, RESUME_ON);
243	
244	    const frames = await connectAndSettle(`${base}?sessionId=${NEVER_ISSUED}`);
245	
246	    expect({
247	      held: await store.count(),
248	      adopted: (await store.get(NEVER_ISSUED)) !== undefined,
249	      minted: (await store.get(frames[0].sessionId ?? '')) !== undefined,
250	    }).toEqual({held: 1, adopted: false, minted: true});
251	  });
252	
253	  it('still calls onDisconnect with the session id when a socket closes under resume', async () => {
254	    const {disconnected, base} = await startEngine(new InMemorySessionStore(), RESUME_ON);
255	
256	    const first = await firstTurn(base);
257	    await eventually(() => disconnected.length > 0);
258	
259	    expect(disconnected).toEqual([first]);
260	  });
261	
262	  it('keeps the credentials of the socket that resumed a session when the socket it replaced closes', async () => {
263	    const store = new InMemorySessionStore();
264	    const {base, disconnected, firstServerClose} = await startEngine(store, RESUME_ON);
265	    const replaced = open(base, 'old');
266	    const [greeting] = (await once(replaced, 'message')) as [Buffer];
267	    const sessionId = (JSON.parse(String(greeting)) as Frame).sessionId ?? '';
268	
269	    const frames = await connectAndSettle(`${base}?sessionId=${sessionId}`, 'new');
270	    replaced.close();
271	    await firstServerClose;
272	
273	    const held = await store.get(sessionId);
274	    expect({resumed: frames[0].resumed, disconnected, authorization: held?.authHeaders?.authorization}).toEqual({
275	      resumed: true,
276	      disconnected: [sessionId],
277	      authorization: 'Bearer new',
278	    });
279	  });
280	
281	  it('gives a session back the credentials of a socket still open when the socket that resumed it closes', async () => {
282	    const store = new InMemorySessionStore();
283	    const {base} = await startEngine(store, RESUME_ON);
284	    const first = open(base, 'first');
285	    const [greeting] = (await once(first, 'message')) as [Buffer];
286	    const sessionId = (JSON.parse(String(greeting)) as Frame).sessionId ?? '';
287	    const second = open(`${base}?sessionId=${sessionId}`, 'second');
288	    await once(second, 'message');
289	    const held = await store.get(sessionId);
290	    const whileBothOpen = held?.authHeaders?.authorization;
291	
292	    second.close();
293	    await eventually(() => held?.authHeaders?.authorization !== whileBothOpen);
294	
295	    expect({whileBothOpen, afterSecondCloses: held?.authHeaders?.authorization}).toEqual({
296	      whileBothOpen: 'Bearer second',
297	      afterSecondCloses: 'Bearer first',
298	    });
299	  });
300	
301	  it('tells onConnect whether a connection started its session or resumed it', async () => {
302	    const {base, connects} = await startEngine(new InMemorySessionStore(), RESUME_ON);
303	    const first = await firstTurn(base);
304	
305	    await connectAndSettle(`${base}?sessionId=${first}`);
306	
307	    expect(connects).toEqual([
308	      {sessionId: first, resumed: false},
309	      {sessionId: first, resumed: true},
310	    ]);
311	  });
312	
313	  it('resumes the id its store knows and starts fresh for one it does not', async () => {
314	    const store = new InMemorySessionStore();
315	    const known = await store.create('known', 'u1');
316	    known.entries.push({role: 'user', content: 'earlier', timestamp: '2026-09-30T08:00:00.000Z'});
317	    const {base} = await startEngine(store, RESUME_ON);
318	
319	    const resumed = await connectAndSettle(`${base}?sessionId=known`);
320	    const fresh = await connectAndSettle(`${base}?sessionId=unknown`);
321	
322	    expect({resumed: resumed[0], fresh: fresh[0]}).toMatchObject({
323	      resumed: {sessionId: 'known', resumed: true, entryCount: 1},
324	      fresh: {resumed: false},
325	    });
326	  });
327	
328	  it('replays a suppressed entry as a skip, so the client never sees text a tool suppressed', async () => {
329	    const store = new InMemorySessionStore();
330	    const known = await store.create('known', 'u1');
331	    known.entries.push(
332	      {role: 'user', content: 'hello', timestamp: '2026-09-30T08:00:00.000Z'},
333	      {
334	        role: 'assistant',
335	        content: 'hidden',
336	        timestamp: '2026-09-30T08:00:01.000Z',
337	        isStreaming: false,
338	        suppressed: true,
339	      }
340	    );
341	    const {base} = await startEngine(store, RESUME_ON);
342	
343	    const frames = await connectAndSettle(`${base}?sessionId=known`);
344	
345	    expect({
346	      types: frames.map(({type, index}) => (index === undefined ? type : `${type} ${index}`)),
347	      leaked: JSON.stringify(frames).includes('hidden'),
348	    }).toEqual({types: ['connected', 'entry_upsert 0', 'entry_skip 1', 'pong'], leaked: false});
349	  });
350	
351	  it('replays an answer suppressed while it was still open as skips, as blank as the live client was left', async () => {
352	    const {base} = await startEngine(new InMemorySessionStore(), RESUME_ON, suppressingMidAnswer);
353	    const first = await firstTurn(base);
354	
355	    const frames = await connectAndSettle(`${base}?sessionId=${first}`);
356	
357	    const replayed = JSON.stringify(frames);
358	    expect({
359	      types: frames.map(({type, index}) => (index === undefined ? type : `${type} ${index}`)),
360	      leaked: ['before', 'after'].filter(word => replayed.includes(word)),
361	    }).toEqual({types: ['connected', 'entry_upsert 0', 'entry_skip 1', 'entry_skip 2', 'pong'], leaked: []});
362	  });
363	
364	  it('replays an entry whose turn is still running as finished and truncated, leaving the stored entry as it is', async () => {
365	    const store = new InMemorySessionStore();
366	    const known = await store.create('known', 'u1');
367	    known.entries.push({role: 'user', content: 'hello', timestamp: '2026-09-30T08:00:00.000Z'}, {...HALF_ANSWER});
368	    const {base} = await startEngine(store, RESUME_ON);
369	
370	    const frames = await connectAndSettle(`${base}?sessionId=known`);
371	
372	    expect({replayed: upserts(frames)[1], stored: known.entries[1]}).toEqual({
373	      replayed: {index: 1, entry: {...HALF_ANSWER, isStreaming: false, truncated: true}},
374	      stored: HALF_ANSWER,
375	    });
376	  });
377	
378	  it('keeps a resumed session whose socket closed before the replay, rather than evicting it', async () => {
379	    const inner = new InMemorySessionStore();
380	    const known = await inner.create('known', 'u1');
381	    known.entries.push({role: 'user', content: 'earlier', timestamp: '2026-09-30T08:00:00.000Z'});
382	    const lookupHeld = deferredRelease();
383	    const evicted: string[] = [];
384	    const store: SessionStore = {
385	      create: (sessionId, userId, options) => inner.create(sessionId, userId, options),
386	      get: async sessionId => {
387	        await lookupHeld.until;
388	        return inner.get(sessionId);
389	      },
390	      delete: sessionId => inner.delete(sessionId),
391	      count: () => inner.count(),
392	      clear: () => inner.clear(),
393	      evict: sessionId => {
394	        evicted.push(sessionId);
395	        return inner.evict(sessionId);
396	      },
397	    };
398	    const {base, firstServerClose} = await startEngine(store, RESUME_ON);
399	
400	    const client = open(`${base}?sessionId=known`);
401	    await once(client, 'open');
402	    // Terminated, not closed: the server holds the socket paused across the lookup, so it never reads a close frame.
403	    client.terminate();
404	    await firstServerClose;
405	    lookupHeld.release();
406	    await new Promise(resolve => setTimeout(resolve, 50));
407	
408	    const kept = inner.get('known');
409	    expect({evicted, kept: kept?.entries.length}).toEqual({evicted: [], kept: 1});
410	  });
411	
412	  it('with resume off, still completes a handshake at /hal/ws/undefined and mints an id', async () => {
413	    const {base} = await startEngine(new InMemorySessionStore());
414	
415	    const frames = await connectAndSettle(`${base}/undefined`);
416	
417	    expect(frames[0]).toMatchObject({type: 'connected', sessionId: expect.stringMatching(/^[0-9a-f-]{36}$/)});
418	  });
419	
420	  it('still types a connected frame literal that carries neither resume field', () => {
421	    const legacy: ConnectedMessage = {type: 'connected', sessionId: 's1', message: 'hi', examplePrompts: []};
422	
423	    expect(Object.keys(legacy)).toEqual(['type', 'sessionId', 'message', 'examplePrompts']);
424	  });
425	});
426	
427	describe('continuing the latest session', () => {
428	  it('with latest on, rejoins the most recently active session of a user whose connect names none', async () => {
429	    const store = storeWith([
430	      ['older', 'u1', '2026-09-30T08:00:00.000Z'],
431	      ['newer', 'u1', '2026-09-30T09:00:00.000Z'],
432	      ['theirs', 'u2', '2026-09-30T10:00:00.000Z'],
