`within` helper with clearable timer:

```ts
const within = async <T>(pending: Promise<T>, ifNever: string): Promise<T> => {
  let giveUp: NodeJS.Timeout | undefined;
  try {
    return await Promise.race([pending, new Promise<never>((_, reject) => {
      giveUp = setTimeout(() => reject(new Error(ifNever)), 2000);
    })]);
  } finally {
    clearTimeout(giveUp);
  }
};
```

